#include <stdlib.h>
#include <string.h>
#include <immintrin.h>

#if defined(__AVX512F__)
#define MR 8
#define NR 32
#elif defined(__AVX2__) && defined(__FMA__)
#define MR 6
#define NR 16
#else
#define MR 4
#define NR 16
#endif

#define KC 256
#define MC 128
#define JC (NR * 2)

static inline void pack_a(const float *A, float *Ap, int n, int i0, int pc, int kc)
{
    int mr = n - i0 < MR ? n - i0 : MR;
    for (int k = 0; k < kc; k++) {
        float *d = Ap + (size_t)k * MR;
        int r = 0;
        for (; r < mr; r++) d[r] = A[(size_t)(i0 + r) * n + pc + k];
        for (; r < MR; r++) d[r] = 0.0f;
    }
}

static inline void pack_b(const float *B, float *Bp, int n, int j0, int pc, int kc)
{
    int nr = n - j0 < NR ? n - j0 : NR;
    for (int k = 0; k < kc; k++) {
        const float *s = B + (size_t)(pc + k) * n + j0;
        float *d = Bp + (size_t)k * NR;
        if (nr == NR) {
            memcpy(d, s, NR * sizeof(float));
        } else {
            int c = 0;
            for (; c < nr; c++) d[c] = s[c];
            for (; c < NR; c++) d[c] = 0.0f;
        }
    }
}

static inline void store_tile(const float *tmp, float *C, int ldc, int mr, int nr, int first)
{
    for (int r = 0; r < mr; r++) {
        float *cr = C + (size_t)r * ldc;
        const float *tr = tmp + r * NR;
        if (first)
            for (int c = 0; c < nr; c++) cr[c] = tr[c];
        else
            for (int c = 0; c < nr; c++) cr[c] += tr[c];
    }
}

#if defined(__AVX512F__)

static inline void kernel(int kc, const float *restrict Ap, const float *restrict Bp,
                          float *restrict C, int ldc, int mr, int nr, int first)
{
    __m512 c0[MR], c1[MR];
#pragma GCC unroll 8
    for (int r = 0; r < MR; r++) {
        c0[r] = _mm512_setzero_ps();
        c1[r] = _mm512_setzero_ps();
    }
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_load_ps(Bp);
        __m512 b1 = _mm512_load_ps(Bp + 16);
#pragma GCC unroll 8
        for (int r = 0; r < MR; r++) {
            __m512 a = _mm512_set1_ps(Ap[r]);
            c0[r] = _mm512_fmadd_ps(a, b0, c0[r]);
            c1[r] = _mm512_fmadd_ps(a, b1, c1[r]);
        }
        Ap += MR;
        Bp += NR;
    }
    if (mr == MR && nr == NR) {
#pragma GCC unroll 8
        for (int r = 0; r < MR; r++) {
            float *cr = C + (size_t)r * ldc;
            if (!first) {
                c0[r] = _mm512_add_ps(c0[r], _mm512_loadu_ps(cr));
                c1[r] = _mm512_add_ps(c1[r], _mm512_loadu_ps(cr + 16));
            }
            _mm512_storeu_ps(cr, c0[r]);
            _mm512_storeu_ps(cr + 16, c1[r]);
        }
    } else {
        float tmp[MR * NR] __attribute__((aligned(64)));
        for (int r = 0; r < MR; r++) {
            _mm512_store_ps(tmp + r * NR, c0[r]);
            _mm512_store_ps(tmp + r * NR + 16, c1[r]);
        }
        store_tile(tmp, C, ldc, mr, nr, first);
    }
}

#elif defined(__AVX2__) && defined(__FMA__)

static inline void kernel(int kc, const float *restrict Ap, const float *restrict Bp,
                          float *restrict C, int ldc, int mr, int nr, int first)
{
    __m256 c0[MR], c1[MR];
#pragma GCC unroll 6
    for (int r = 0; r < MR; r++) {
        c0[r] = _mm256_setzero_ps();
        c1[r] = _mm256_setzero_ps();
    }
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_load_ps(Bp);
        __m256 b1 = _mm256_load_ps(Bp + 8);
#pragma GCC unroll 6
        for (int r = 0; r < MR; r++) {
            __m256 a = _mm256_broadcast_ss(Ap + r);
            c0[r] = _mm256_fmadd_ps(a, b0, c0[r]);
            c1[r] = _mm256_fmadd_ps(a, b1, c1[r]);
        }
        Ap += MR;
        Bp += NR;
    }
    if (mr == MR && nr == NR) {
#pragma GCC unroll 6
        for (int r = 0; r < MR; r++) {
            float *cr = C + (size_t)r * ldc;
            if (!first) {
                c0[r] = _mm256_add_ps(c0[r], _mm256_loadu_ps(cr));
                c1[r] = _mm256_add_ps(c1[r], _mm256_loadu_ps(cr + 8));
            }
            _mm256_storeu_ps(cr, c0[r]);
            _mm256_storeu_ps(cr + 8, c1[r]);
        }
    } else {
        float tmp[MR * NR] __attribute__((aligned(32)));
        for (int r = 0; r < MR; r++) {
            _mm256_store_ps(tmp + r * NR, c0[r]);
            _mm256_store_ps(tmp + r * NR + 8, c1[r]);
        }
        store_tile(tmp, C, ldc, mr, nr, first);
    }
}

#else

static inline void kernel(int kc, const float *restrict Ap, const float *restrict Bp,
                          float *restrict C, int ldc, int mr, int nr, int first)
{
    float acc[MR * NR];
    for (int i = 0; i < MR * NR; i++) acc[i] = 0.0f;
    for (int k = 0; k < kc; k++) {
        for (int r = 0; r < MR; r++) {
            float a = Ap[r];
            for (int c = 0; c < NR; c++) acc[r * NR + c] += a * Bp[c];
        }
        Ap += MR;
        Bp += NR;
    }
    store_tile(acc, C, ldc, mr, nr, first);
}

#endif

static void *alloc64(size_t bytes)
{
    bytes = (bytes + 63) & ~(size_t)63;
    if (bytes == 0) bytes = 64;
    return aligned_alloc(64, bytes);
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npan_a = (n + MR - 1) / MR;
    int npan_b = (n + NR - 1) / NR;
    int kcmax = n < KC ? n : KC;

    float *Apk = (float *)alloc64((size_t)npan_a * MR * kcmax * sizeof(float));
    float *Bpk = (float *)alloc64((size_t)npan_b * NR * kcmax * sizeof(float));

    const int mpb = MC / MR;
    const int npb = JC / NR;
    int nrb = (npan_a + mpb - 1) / mpb;
    int ncb = (npan_b + npb - 1) / npb;
    int npack = npan_a + npan_b;

#pragma omp parallel
    for (int pc = 0; pc < n; pc += KC) {
        int kc = n - pc < KC ? n - pc : KC;
        int first = (pc == 0);

        /* Cooperative packing of all of A and B for this k-slice. */
#pragma omp for schedule(dynamic, 4)
        for (int t = 0; t < npack; t++) {
            if (t < npan_a)
                pack_a(A, Apk + (size_t)t * MR * kc, n, t * MR, pc, kc);
            else {
                int q = t - npan_a;
                pack_b(B, Bpk + (size_t)q * NR * kc, n, q * NR, pc, kc);
            }
        }

        /* Fine-grained dynamic compute tasks; no packing inside. */
#pragma omp for collapse(2) schedule(dynamic, 1)
        for (int rb = 0; rb < nrb; rb++) {
            for (int cb = 0; cb < ncb; cb++) {
                int ip0 = rb * mpb, ip1 = ip0 + mpb < npan_a ? ip0 + mpb : npan_a;
                int jp0 = cb * npb, jp1 = jp0 + npb < npan_b ? jp0 + npb : npan_b;
                for (int jp = jp0; jp < jp1; jp++) {
                    int j0 = jp * NR;
                    int nr = n - j0 < NR ? n - j0 : NR;
                    const float *bp = Bpk + (size_t)jp * NR * kc;
                    for (int ip = ip0; ip < ip1; ip++) {
                        int i0 = ip * MR;
                        int mr = n - i0 < MR ? n - i0 : MR;
                        kernel(kc, Apk + (size_t)ip * MR * kc, bp,
                               C + (size_t)i0 * n + j0, n, mr, nr, first);
                    }
                }
            }
        }
    }

    free(Apk);
    free(Bpk);
}
